self.addEventListener('message', (e) => {
  if (e.data === 'ping') e.ports[0]?.postMessage(KEY_ID);
  if (e.data === 'warm') e.waitUntil(warming ||= warm().finally(() => { warming = null; }));
});
async function warm() {
  const idx = await open(BASE + 'lock-index', TYPES.json, true);
  if (!idx) return;
  const all = [...(await idx.json()), ...OPEN];
  const c = await caches.open(CACHE);
  const have = new Set((await c.keys()).map((r) => r.url));
  const todo = all.filter((u) => !have.has(new URL(u, location.href).href));
  const next = async () => { for (let u; (u = todo.shift()); ) await fetch(u).then((r) => r.ok && c.put(u, r)).catch(() => {}); };
  await Promise.all([next(), next(), next(), next()]);
}

async function sealedBytes(url, fresh) {
  const c = await caches.open(CACHE);
  if (fresh) {
    try {
      const r = await fetch(url, { cache: 'no-cache' });
      if (r.ok) { c.put(url, r.clone()); return r.arrayBuffer(); }
      if (r.status === 404) return null;
    } catch { /* offline: the stored copy */ }
  }
  let r = await c.match(url);
  if (!r) { r = await fetch(url); if (!r.ok) return null; c.put(url, r.clone()); }
  return r.arrayBuffer();
}
/* the decrypted file for a path the page asked for, or null */
async function open(pathname, type, fresh) {
  const rec = await getRec();
  if (!rec) return null;
  const buf = await sealedBytes(await nameOf(rec.nameKey, pathname), fresh).catch(() => null);
  if (!buf) return null;
  try {
    const body = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: buf.slice(0, 12) }, rec.key, buf.slice(12));
    return new Response(body, { headers: { 'content-type': type } });
  } catch {
    // made for another password: ask again
    await forget();
    return null;
  }
}
const gate = (req) => fetch(req).catch(() => caches.match(BASE));
const page = (p) => open(p, TYPES.html, true).then((r) => r || open(BASE + '404.html', TYPES.html, true));

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin || !url.pathname.startsWith(BASE)) return;
  const p = url.pathname;
  const ext = /\.([a-z0-9]+)$/i.exec(p.slice(p.lastIndexOf('/')))?.[1]?.toLowerCase();
  if (req.mode === 'navigate' && !ext) {
    if (!p.endsWith('/')) { e.respondWith(Response.redirect(p + '/' + url.search + url.hash, 301)); return; }
    e.respondWith(page(p).then((r) => r || gate(req)));
    return;
  }
  if (isOpen(p)) {
    e.respondWith(fetch(req).catch(() => caches.match(req, { ignoreSearch: true })));
    return;
  }
  if (ext === 'html') { e.respondWith(page(p).then((r) => r || gate(req))); return; }
  e.respondWith(open(p, TYPES[ext] || 'application/octet-stream', p === BASE + 'version.json')
    .then((r) => r || fetch(req)));
});
